const out = $('Project Planner & Scope Agent').first().json.output;

let aiResponse;

if (Array.isArray(out)) {
  aiResponse = out
    .flatMap(item => item?.content ?? [])
    .map(c => c?.text)
    .filter(Boolean)
    .join('\n\n');
} else if (typeof out === 'string') {
  aiResponse = out;
}

if (!aiResponse) {
  aiResponse = 'No response generated. Raw output: ' + JSON.stringify(out);
}

return [{ json: { text: aiResponse } }];

