const items = $input.all();

// Take only a safe slice or concise summary of the items/files to prevent token overflow
const description = items[0]?.json?.text || items[0]?.json?.data || "Project MIRA Status Data";


// Map and limit data rows if the files contain large lists or logs
const tasks = JSON.stringify(items.slice(0, 50).map(item => item.json));

const rawCombinedPrompt = `
=== PROJECT DESCRIPTION ===
${description}

=== PROJECT DATA & TASKS (TRUNCATED) ===
${tasks}
`.trim();

const safePrompt = rawCombinedPrompt
  .replace(/\\/g, '\\\\')
  .replace(/"/g, '\\"')
  .replace(/\r?\n/g, '\\n');

return [{
  json: {
    combinedPrompt: safePrompt
  }
}];

const items = $input.all();
const currentItem = items[0]?.json || {};

const rawContent = currentItem.choices?.[0]?.message?.content || 
                  currentItem.body?.choices?.[0]?.message?.content || 
                  currentItem.data?.choices?.[0]?.message?.content ||
                  "No report generated.";

// Convert double-escaped literal '\n' sequences into actual clean newlines
const cleanedReport = rawContent
  .replace(/\\n/g, '\n')
  .replace(/\n\s*-\s*\n/g, '\n- '); // Fixes orphan bullet points like "\n-\n"

return [{
  json: {
    reportContent: cleanedReport,
    timestamp: new Date().toISOString()
  }
}];

